// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address target, uint256 tokenId, bytes calldata data) public {
        vm.assume(target != address(0) && target != address(c));
        // Deploy an adversarial callee whose onERC721Received returns ERC721TokenReceiver.onERC721Received.selector
        // (the safeTransferFrom implementations use the interface, so we need a compliant receiver that does not revert).
        CompliantReceiver receiver = new CompliantReceiver();
        // The bug exists in ERC721TokenReceiver's onERC721Received; we call it directly via the target's safeTransferFrom
        // that invokes the receiver.  We route through c's flashLoan to invoke safeTransferFrom on an ERC721 token.
        // Use a minimal ERC721 token that c trusts for the test.
        MockERC721 tokenContract = new MockERC721();
        tokenContract.mint(address(c), tokenId);

        // The flashLoan function calls safeTransferFrom on the token, which eventually calls onERC721Received on the receiver.
        // Pre-fund c with any required native token fee.
        vm.deal(address(c), 1 ether);
        vm.prank(address(c));
        // flashLoan will call tokenContract.safeTransferFrom, which will call receiver.onERC721Received.
        // We expect the flashLoan to succeed only if the return selector is correct.
        // In the reference, it returns ERC721TokenReceiver.onERC721Received.selector; in the mutant, bytes4(0).
        // The flashLoan function checks the return value and reverts if it doesn't match keccak256("onFlashLoan")
        // Wait, that check is on the IERC3156FlashBorrower receiver, not the ERC721 receiver.  We need to call onERC721Received directly.
        // The simplest: call c.onERC721Received directly (it inherits from ERC721TokenReceiver).
        bytes4 returned = c.onERC721Received(address(0), address(0), 0, data);
        assertTrue(returned == ERC721TokenReceiver.onERC721Received.selector);
    }
}

contract MockERC721 {
    mapping(uint256 => address) private _owners;
    function mint(address to, uint256 id) external {
        _owners[id] = to;
    }
    function ownerOf(uint256 id) external view returns (address) {
        return _owners[id];
    }
}

contract CompliantReceiver is ERC721TokenReceiver {}
